import{ThemeEvents,VariantUpdateEvent}from"@theme/events";import{Component}from"@theme/component";class ProductPrice extends Component{connectedCallback(){super.connectedCallback();const e=this.closest(".shopify-section, dialog");e&&e.addEventListener(ThemeEvents.variantUpdate,this.updatePrice)}disconnectedCallback(){super.disconnectedCallback();const e=this.closest(".shopify-section, dialog");e&&e.removeEventListener(ThemeEvents.variantUpdate,this.updatePrice)}updatePrice=e=>{if(e.detail.data.newProduct)this.dataset.productId=e.detail.data.newProduct.id;else if(e.target instanceof HTMLElement&&e.target.dataset.productId!==this.dataset.productId)return;const{priceContainer:t,volumePricingNote:c}=this.refs,r=e.detail.data.html.querySelector(`product-price[data-block-id="${this.dataset.blockId}"]`);if(!r)return;const n=r.querySelector('[ref="priceContainer"]');n&&t&&t.replaceWith(n);const o=r.querySelector('[ref="volumePricingNote"]');o?c?c.replaceWith(o):n?.insertAdjacentElement("afterend",o.cloneNode(!0)):c?.remove()}}customElements.get("product-price")||customElements.define("product-price",ProductPrice);